const vm = require('node:vm');
const fs = require('node:fs');
const assert = require('node:assert/strict');
const nodes = new Map();
const getNode = id => { if(!nodes.has(id)) nodes.set(id,{innerHTML:'',style:{},classList:{add(){},remove(){}}}); return nodes.get(id); };
const sandbox = {document:{getElementById:getNode,querySelector:()=>null,querySelectorAll:()=>[],addEventListener(){},body:{style:{}}},window:{addEventListener(){}},location:{hash:''},requestAnimationFrame:fn=>fn(),setTimeout:()=>0,clearTimeout(){},innerWidth:1200,crypto:require('node:crypto').webcrypto,Blob,File,URL};
vm.createContext(sandbox);
vm.runInContext(fs.readFileSync('qr-library.js','utf8'),sandbox);
vm.runInContext(fs.readFileSync('passes.js','utf8'),sandbox);
vm.runInContext(fs.readFileSync('students-data.js','utf8'),sandbox);
vm.runInContext(fs.readFileSync('promotions.js','utf8'),sandbox);
vm.runInContext(fs.readFileSync('app.js','utf8'),sandbox);
assert.match(getNode('app').innerHTML,/Smarter Hostel/);
assert.doesNotMatch(getNode('app').innerHTML,/Aarav Sharma|Karan Joshi/);
let routes=0;
vm.runInContext(`for (const r of Object.keys(roles)) { role=r; for(const p of roles[r].nav) { page=p; dashboard(); if(!document.getElementById('app').innerHTML.includes(p))throw Error(r+'/'+p); } }`,sandbox);
routes=vm.runInContext('Object.values(roles).reduce((n,r)=>n+r.nav.length,0)',sandbox);
vm.runInContext("role='Mentor';page='Dashboard';dashboard()",sandbox);
assert.doesNotMatch(getNode('app').innerHTML,/Guardian|Gate activity|CMP-0284/);
vm.runInContext("role='Warden';page='Dashboard';action('confirm-approve:1')",sandbox);
assert.equal(vm.runInContext('passes[1].status',sandbox),'Approved');
vm.runInContext("action('confirm-reject:2')",sandbox);
assert.equal(vm.runInContext('passes[2].status',sandbox),'Rejected');
vm.runInContext("role='Mentor';action('accept:0')",sandbox);
assert.equal(vm.runInContext('sessions[0].status',sandbox),'Accepted');
assert.match(vm.runInContext('agenda()',sandbox),/Academic planning/);
vm.runInContext("role='Admin';action('registration-approve:0')",sandbox);
assert.equal(vm.runInContext('registrations[0][5]',sandbox),'Approved');
assert.equal(vm.runInContext("esc('<script>')",sandbox),'&lt;script&gt;');
console.log(`Passed: landing privacy, ${routes} role routes, mentor scope, pass approval/rejection, session agenda, registration approval, HTML escaping.`);
for(const [time,expected] of [['04:59:59',false],['05:00:00',true],['21:59:59',true],['22:00:00',false],['23:00:00',false]]) {
  assert.equal(vm.runInContext(`quickWindow(new Date('2026-09-25T${time}+05:30')).open`,sandbox),expected,time);
}
vm.runInContext("role='Student'",sandbox);
assert.ok(vm.runInContext("createQuickPass('Exit',new Date('2026-09-25T04:59:59+05:30')).error",sandbox));
assert.ok(vm.runInContext("createQuickPass('Other',new Date('2026-09-25T12:00:00+05:30')).error",sandbox));
vm.runInContext("createQuickPass('Exit',new Date('2026-09-25T21:58:00+05:30'))",sandbox);
assert.equal(vm.runInContext('quickPass.expiresAt',sandbox),new Date('2026-09-25T22:00:00+05:30').getTime());
assert.equal(vm.runInContext("quickIsValid(new Date('2026-09-25T22:00:00+05:30'))",sandbox),false);
vm.runInContext("createQuickPass('Entry',new Date('2026-09-25T12:00:00+05:30'))",sandbox);
assert.equal(vm.runInContext('quickPass.expiresAt - quickPass.issuedAt',sandbox),600000);
assert.match(vm.runInContext('quickQRMarkup()',sandbox),/<svg/);
vm.runInContext("role='Mentor'",sandbox);
assert.ok(vm.runInContext("createQuickPass('Exit',new Date('2026-09-25T12:00:00+05:30')).error",sandbox));
console.log('Passed: Quick Pass time boundaries, 10-minute expiry, 10 PM cutoff, movement validation, role guard and QR encoding.');
(async()=>{
  const run=code=>vm.runInContext(code,sandbox);
  run("role='Admin'");
  assert.ok(run("promoteStudent('STU-2026-001','missing',true).error"));
  const profileBefore=run("JSON.stringify({id:currentStudent().id,name:currentStudent().name,course:currentStudent().course,email:currentStudent().email,phone:currentStudent().phone,guardian:currentStudent().guardian,mess:currentStudent().mess})");
  const bedsBefore=run('hostelInventory().reduce((n,h)=>n+h.available,0)');
  run("role='Student'");
  assert.ok((await run("storeMarksheet(new File(['bad'], 'marksheet.png',{type:'image/png'}))")).error);
  assert.ok((await run("storeMarksheet(new File([new Uint8Array(5*1024*1024+1)],'too-large.png'))")).error);
  await run("storeMarksheet(new File([new Uint8Array([137,80,78,71,13,10,26,10,0])], 'sample.png',{type:'image/png'}))");
  const documentId=run('currentStudent().marksheet.id');
  assert.ok(run(`verifyMarksheet('STU-2026-001','${documentId}',true).error`));
  run("role='Admin'");
  assert.ok(run(`verifyMarksheet('STU-2026-001','${documentId}',true).error`),'unviewed document must be blocked');
  run("reviewMarksheet('STU-2026-001')");
  assert.ok(run(`verifyMarksheet('STU-2026-001','${documentId}',false).error`));
  assert.ok(run("verifyMarksheet('STU-2026-001','stale-document',true).error"));
  assert.ok(run(`verifyMarksheet('STU-2026-001','${documentId}',true).document`));
  assert.ok(run(`promoteStudent('STU-2026-001','${documentId}',false).error`));
  assert.ok(run(`promoteStudent('STU-2026-001','${documentId}',true).student`));
  assert.equal(run('currentStudent().studyYear'),2);
  assert.equal(run('currentStudent().academicYear'),'2027–28');
  assert.equal(run('currentStudent().allocation'),null);
  assert.equal(run('currentStudent().history[0].allocation.room'),'A-204');
  assert.equal(run('currentStudent().documents[0].status'),'Archived');
  assert.equal(run('hostelInventory().reduce((n,h)=>n+h.available,0)'),bedsBefore+1);
  assert.equal(run('roomInventory()[0].occupied'),0);
  assert.equal(run('roomInventory()[0].available'),2);
  assert.equal(run('roomInventory()[1].occupied'),2,'another room must remain unchanged');
  assert.equal(run('roomInventory()[0].total'),2,'capacity stays fixed');
  assert.equal(run("JSON.stringify({id:currentStudent().id,name:currentStudent().name,course:currentStudent().course,email:currentStudent().email,phone:currentStudent().phone,guardian:currentStudent().guardian,mess:currentStudent().mess})"),profileBefore);
  assert.ok(run(`promoteStudent('STU-2026-001','${documentId}',true).error`));
  assert.equal(run('hostelInventory().reduce((n,h)=>n+h.available,0)'),bedsBefore+1);
  run("role='Student'");
  assert.ok(run("createQuickPass('Exit',new Date('2026-09-25T12:00:00+05:30')).error"));
  // Final-year and replacement verification guards.
  run("currentStudent().studyYear=4");
  await run("storeMarksheet(new File([new Uint8Array([137,80,78,71,13,10,26,10,0])], 'final-year.png',{type:'image/png'}))");
  run("role='Admin';reviewMarksheet('STU-2026-001')");
  assert.ok(run("verifyMarksheet('STU-2026-001',currentStudent().marksheet.id,true).error"));
  console.log('Passed: upload validation, admin verification, confirmation, profile preservation, year increment, allocation history, one-bed release, unchanged room capacity, duplicate/stale/final-year guards.');
})().catch(error=>{console.error(error);process.exitCode=1;});
